      "Mit dem Verlassen verlieren Sie den Zugriff. Ihr Partner behält den Arbeitsbereich, und mit einer neuen Einladung kommen Sie jederzeit zurück.",
    leave_couple_body_owner:
      "Sie haben diesen Arbeitsbereich angelegt, Eigentümer können ihn nicht verlassen. Wenn Sie ihn beenden möchten, starten Sie stattdessen Pausieren + Löschung in 30 Tagen.",
    leave_couple_button: "Verlassen",
